import{_ as t,o as r,c as a,a2 as c}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"The network stack","description":"","frontmatter":{},"headers":[],"relativePath":"arch/network-stack.md","filePath":"arch/network-stack.md"}'),s={name:"arch/network-stack.md"};function n(o,e,i,d,h,l){return r(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="the-network-stack" tabindex="-1">The network stack <a class="header-anchor" href="#the-network-stack" aria-label="Permalink to &quot;The network stack&quot;">​</a></h1><p>Bottom-up, one layer per file under <code>net/</code>:</p><h2 id="nic-drivers-drivers-nic" tabindex="-1">NIC drivers (<code>drivers/nic/</code>) <a class="header-anchor" href="#nic-drivers-drivers-nic" aria-label="Permalink to &quot;NIC drivers (`drivers/nic/`)&quot;">​</a></h2><p>e1000, e1000e, igb, ixgbe (Intel families); rtl8139 and the rtl8169-family (8168/8125/810x); BCM57xx. Each registers through the L1 driver_nic interface (<code>driver_nic_register</code> / send / recv / link_status / get_mac). DMA descriptors, interrupt-driven RX where the card supports it, and per-card quirk handling live in the driver files - bring-up notes per family are under <a href="./../drivers/">../drivers/</a>.</p><h2 id="ethernet-arp" tabindex="-1">Ethernet + ARP <a class="header-anchor" href="#ethernet-arp" aria-label="Permalink to &quot;Ethernet + ARP&quot;">​</a></h2><p>Frame RX dispatch by ethertype; the ARP cache with expiry; <code>arp</code> command.</p><h2 id="ipv4-icmp-udp" tabindex="-1">IPv4 / ICMP / UDP <a class="header-anchor" href="#ipv4-icmp-udp" aria-label="Permalink to &quot;IPv4 / ICMP / UDP&quot;">​</a></h2><p>Fragment handling, ICMP echo (the <code>ping</code> command), UDP sockets - DNS rides on UDP with the resolver configured through the network setup.</p><h2 id="tcp-net-net-core-c-net-tcp-cc-c" tabindex="-1">TCP (<code>net/net_core.c</code> + <code>net_tcp_cc.c</code>) <a class="header-anchor" href="#tcp-net-net-core-c-net-tcp-cc-c" aria-label="Permalink to &quot;TCP (`net/net_core.c` + `net_tcp_cc.c`)&quot;">​</a></h2><p>A full state machine with congestion control. The RX checksum chain was a famous bug (BUG-0072: chained internet_checksum() calls complemented twice - every inbound segment was refused; fixed with checksum_raw_add + one fold across pseudo-header and segment). <code>tcpstats</code>, <code>tcpcc_test</code>, <code>tcptest</code> are the observers/tests.</p><h2 id="sockets-for-user-programs" tabindex="-1">Sockets for user programs <a class="header-anchor" href="#sockets-for-user-programs" aria-label="Permalink to &quot;Sockets for user programs&quot;">​</a></h2><p>The socket syscall family (53-syscall surface) backs <code>run select_test</code> style multiplexing and the network user programs.</p><h2 id="tls-1-2-1-3-net-net-tls-c" tabindex="-1">TLS 1.2 / 1.3 (<code>net/net_tls.c</code>) <a class="header-anchor" href="#tls-1-2-1-3-net-net-tls-c" aria-label="Permalink to &quot;TLS 1.2 / 1.3 (`net/net_tls.c`)&quot;">​</a></h2><p>RSA and ECDHE key exchange, X.509 chain verification with the RFC 6125 hostname policy (IP-literal URLs have no reference identity - the mid-handshake disconnect bug was exactly here, BUG-fixed with net_tls_host_is_ip_literal), and the WP-09 trust model: structural bounds always fatal; an un-anchored chain warns and continues; hostname mismatch is fatal only for user-supplied hostnames.</p><h2 id="ssh-client-server-net-ssh-c-net-sshd-c" tabindex="-1">SSH client + server (<code>net_ssh.c</code>, <code>net_sshd.c</code>) <a class="header-anchor" href="#ssh-client-server-net-ssh-c-net-sshd-c" aria-label="Permalink to &quot;SSH client + server (`net_ssh.c`, `net_sshd.c`)&quot;">​</a></h2><p>Key exchange, host keys on /etc, authorized_keys, full session round-trip - the E2E suite logs in with paramiko from the host.</p><h2 id="entropy" tabindex="-1">Entropy <a class="header-anchor" href="#entropy" aria-label="Permalink to &quot;Entropy&quot;">​</a></h2><p>HMAC_DRBG (SP 800-90A) seeded from RDRAND + RDTSC, re-mixed every generate - see <a href="./../internals/drbg-crypto.html">internals/drbg-crypto.md</a>.</p>',18)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
